'use strict';
/**
 * MiniPy v5 battery runner (fast).  Same driving contract as battery.mjs but
 * with a robust stop condition and CPython truth comparison built in.
 *
 *   node run5.cjs <sb3> <cases.json> <out.json> [maxSteps]
 */
const fs = require('fs');
const VM = require('D:/users/OneDrive/Desktop/scratch-vm-test/node_modules/scratch-vm');

const projectPath = process.argv[2];
const casesPath = process.argv[3];
const outPath = process.argv[4];
const MAXSTEPS = Number(process.argv[5] || 60000);

const cases = JSON.parse(fs.readFileSync(casesPath, 'utf8'));

(async () => {
  const vm = new VM();
  await vm.loadProject(fs.readFileSync(projectPath));
  const runtime = vm.runtime;
  const stage = runtime.getTargetForStage();
  const vals = (m) => (m && typeof m.values === 'function') ? [...m.values()] : Object.values(m || {});
  const sv = (n) => vals(stage.variables).find((v) => v.name === n && v.type !== 'list');
  const sl = (n) => vals(stage.variables).find((v) => v.name === n && v.type === 'list');
  const gv = (n) => { const v = sv(n); return v ? v.value : undefined; };
  const gl = (n) => { const l = sl(n); if (!l) return undefined; return Array.isArray(l.value) ? l.value.slice() : [...(l.value || [])]; };
  const setList = (n, arr) => { const l = sl(n); if (!l) return false; l.value.length = 0; for (const x of arr) l.value.push(x); return true; };

  vm.start();
  vm.greenFlag();
  for (let i = 0; i < 10; i++) runtime._step();

  const results = [];
  let totalSteps = 0;
  for (const c of cases) {
    const lines = String(c.code).replace(/\r/g, '').split('\n');
    let out = [], err = '', steps = 0, ms = 0;
    try {
      setList('Code', lines);
      setList('Output', []);
      setList('Names', []); setList('Values', []); setList('Types', []);
      for (const n of ['mode', 'ticket', 'stopreq', 'running']) { const v = sv(n); if (v) v.value = 0; }
      const tk = sv('ticket'); if (tk) tk.value = 1;
      const rn = sv('running'); if (rn) rn.value = 1;
      const sp = sv('speed'); if (sp) sp.value = 1;
      const t0 = Date.now();
      runtime.startHats('event_whenbroadcastreceived', { BROADCAST_OPTION: 'RUN' });
      let stable = 0, lastLen = -1;
      for (; steps < MAXSTEPS; steps++) {
        runtime._step();
        if (steps > 3 && String(gv('running')) === '0') break;
        const L = (gl('Output') || []).length;
        if (L === lastLen) { stable++; if (stable > 400) break; } else { stable = 0; lastLen = L; }
      }
      ms = Date.now() - t0;
      out = (gl('Output') || []).map((x) => String(x));
      err = String(gv('error'));
    } catch (e) {
      err = 'HARNESS: ' + e.message;
    }
    totalSteps += steps;
    results.push({ name: c.name, out, status: String(gv('status')), err, steps, ms });
    process.stdout.write('.');
  }
  process.stdout.write('\n');
  fs.writeFileSync(outPath, JSON.stringify({ project: projectPath, results }, null, 1));

  // ------- compare with CPython truth if present -------
  const truthPath = casesPath.replace(/cases[^/\\]*\.json$/, 'truth.json');
  let pass = 0, fail = 0, noTruth = 0;
  const fails = [];
  if (fs.existsSync(truthPath)) {
    const truth = JSON.parse(fs.readFileSync(truthPath, 'utf8'));
    for (const r of results) {
      const t = truth[r.name];
      if (!t) { noTruth++; continue; }
      const want = (t.out || []).map(String);
      while (want.length && want[want.length - 1] === '') want.pop();
      const got = r.out.slice();
      while (got.length && got[got.length - 1] === '') got.pop();
      let ok = got.join('\n') === want.join('\n');
      if (!ok && got.join('').replace(/\s+/g, '') === want.join('').replace(/\s+/g, '')) ok = true;
      if (!ok && t.err && /Error/.test(r.err) && r.err.indexOf(t.err.split(':')[0]) >= 0) ok = true;
      if (ok) pass++; else { fail++; fails.push({ name: r.name, want, got, err: r.err }); }
    }
  }
  console.log('PASS ' + pass + '  FAIL ' + fail + (noTruth ? ('  (no truth: ' + noTruth + ')') : '') + '   steps=' + totalSteps);
  for (const f of fails.slice(0, 40)) {
    console.log('  x ' + f.name.padEnd(16) + ' want=' + JSON.stringify(f.want).slice(0, 70) +
      ' got=' + JSON.stringify(f.got).slice(0, 70) + (f.err && f.err !== '0' && f.err !== '' ? (' ERR=' + f.err.slice(0, 60)) : ''));
  }
})().catch((e) => { console.error(e); process.exit(1); });

