'use strict';
/**
 * v5 kernel shared macros.  Everything here is BUILD-time JS that expands into
 * flat Scratch blocks; the emitted kernel never calls a custom block from
 * inside another custom block (leaf-only invariant).
 */
const { E, S } = require('../dsl.js');

// ---------------------------------------------------------------- value tags
// A runtime value is a self describing string.  Numbers are stored as their
// bare numeric text (first char is a digit, '-' or '.'), every other kind is
// one tag character followed by the payload.
//   S text      B 0|1      Z        L id   T id   D id   F id   C id   O id
const DIGITS = '0123456789';
const NUMSTART = '0123456789-.';
const isNum = (v) => E.contains(E.str(NUMSTART), E.letter(E.num(1), v));
const isDigit = (c) => E.contains(E.str(DIGITS), c);
const tagOf = (v) => E.letter(E.num(1), v);
const isTag = (v, t) => E.eq(E.letter(E.num(1), v), E.str(t));
const B = (b) => E.str(b ? 'B1' : 'B0');
const NONE = () => E.str('Z');
const num = (v) => E.join(E.str(''), v);          // number -> canonical text
const str = (t) => E.join(E.str('S'), t);
const stmtFail = (msg, line) => S.If(E.eq(E.var('err'), E.str('')), [
  S.set('err', msg),
  S.set('pc', line || E.var('li')),
]);

// payload of a value into dst: O(1) for numbers, char loop otherwise
function payInto(src, dst) {
  return [
    S.set(dst, E.str('')),
    S.If(isNum(src), [
      S.set(dst, src),
    ], [
      S.set('ti', E.num(2)),
      S.Repeat(E.sub(E.slen(src), E.num(1)), [
        S.set(dst, E.join(E.var(dst), E.letter(E.var('ti'), src))),
        S.chg('ti', E.num(1)),
      ]),
    ]),
  ];
}

// case signature: '1' for A-Z, '0' otherwise (same length as src)
function signInto(src, dst) {
  return [
    S.set(dst, E.str('')),
    S.set('ti', E.num(1)),
    S.Repeat(E.slen(src), [
      S.set('c0', E.letter(E.var('ti'), src)),
      S.Costume(E.join(E.str('_'), E.var('c0'))),
      S.set('n0', E.costumeNum()),
      S.If(E.and(E.ge(E.var('n0'), E.num(34)), E.le(E.var('n0'), E.num(59))), [
        S.set(dst, E.join(E.var(dst), E.str('1'))),
      ], [
        S.set(dst, E.join(E.var(dst), E.str('0'))),
      ]),
      S.chg('ti', E.num(1)),
    ]),
  ];
}

// case sensitive string equality: a=b is the cheap case-insensitive filter
function eqCS(a, b) {
  return E.and(E.eq(a, b), E.eq(concat(a, 'sig'), concat(b, 'sig')));
}
// helper that stores the signature in a scratch register and returns it
function concat(a, slot) {
  return S.slot(slot, a);
}
// (S.slot is registered below: an expression that forces a side effect is not
//  possible in Scratch, so eqCS is always expanded through stmtEqCS.)

function stmtSignIfEqual(a, b, dst) {
  return [
    S.set(dst, E.num(1)),
    S.If(E.eq(a, b), signInto(a, 'sg1')),
    S.If(E.eq(a, b), signInto(b, 'sg2')),
    S.If(E.and(E.eq(a, b), E.not(E.eq(E.var('sg1'), E.var('sg2')))), [S.set(dst, E.num(0))]),
  ];
}

