    S.set(dst, E.var('hTop')),
    S.lset('LStart', E.var(dst), E.add(E.len('LArr'), E.num(1))),
    S.lset('LCount', E.var(dst), E.num(0)),
    S.lset('LCap', E.var(dst), E.num(0)),
