};

'use strict';
/**
 * v5 kernel shared macros (build-time JS -> flat Scratch blocks).
 */
const { E, S } = require('../dsl.js');

// ------------------------------------------------ value representation
const DIGITS = '0123456789';
const NUMSTART = '0123456789-.';
const LETTERS = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_';
const NAMECH = LETTERS + DIGITS;
const isNum = (v) => E.contains(E.str(NUMSTART), E.letter(E.num(1), v));
const isDigit = (c) => E.contains(E.str(DIGITS), c);
const isAlpha = (c) => E.contains(E.str(LETTERS), c);
const isNameCh = (c) => E.contains(E.str(NAMECH), c);
const tagOf = (v) => E.letter(E.num(1), v);
const isTag = (v, t) => E.eq(E.letter(E.num(1), v), E.str(t));
const Bv = (b) => E.str(b ? 'B1' : 'B0');
const NONE = () => E.str('Z');
const txt = (t) => E.join(E.str('S'), t);
const numtxt = (v) => E.join(E.str(''), v);

// a console line (Output is capped at 300 like v4)
const outLine = (e) => [
  S.ladd('Output', e),
  S.While(E.gt(E.len('Output'), E.num(300)), [S.ldel('Output', E.num(1))]),
  S.set('outpage', E.num(1)),
  S.set('dirty', E.num(1)),
];

// error latch: first error wins, records the source line
const failAt = (msg, line) => S.If(E.eq(E.var('err'), E.str('')), [
  S.set('err', msg),
  S.set('pc', line),
]);

// character code (ASCII) via the Interpreter costume table; 31 + costume no.
const charCode = (cExpr, dst) => [
  S.Costume(E.join(E.str('_'), cExpr)),
  S.set(dst, E.costumeNum()),
];
const isUpperChar = (nExpr) => E.and(E.ge(nExpr, E.num(34)), E.le(nExpr, E.num(59)));

// payload of a value into dst
function payInto(src, dst) {
  return [
    S.set(dst, E.str('')),
    S.If(isNum(src), [S.set(dst, src)], [
      S.set('ti', E.num(2)),
      S.Repeat(E.sub(E.slen(src), E.num(1)), [
        S.set(dst, E.join(E.var(dst), E.letter(E.var('ti'), src))),
        S.chg('ti', E.num(1)),
      ]),
    ]),
  ];
}

// case signature of a string into dst ('1' for A-Z, '0' otherwise)
function signInto(src, dst) {
  return [
    S.set(dst, E.str('')),
    S.set('ti', E.num(1)),
    S.Repeat(E.slen(src), [
      S.set('c9', E.letter(E.var('ti'), src)),
      ...charCode(E.var('c9'), 'n9'),
      S.If(isUpperChar(E.var('n9')), [
        S.set(dst, E.join(E.var(dst), E.str('1'))),
      ], [
        S.set(dst, E.join(E.var(dst), E.str('0'))),
      ]),
      S.chg('ti', E.num(1)),
    ]),
  ];
}

// push a value onto a manual-pointer stack
const pushL = (list, ptr, v) => [
  S.chg(ptr, E.num(1)),
  S.If(E.gt(E.var(ptr), E.len(list)), [S.ladd(list, v)], [S.lset(list, E.var(ptr), v)]),
];

module.exports = {
  DIGITS, NUMSTART, LETTERS, NAMECH, isNum, isDigit, isAlpha, isNameCh, tagOf, isTag,
  Bv, NONE, txt, numtxt, outLine, failAt, charCode, isUpperChar,
  payInto, signInto, pushL,
};

'use strict';
/**
 * v5 Lexer - linear character state machine, no Scratch recursion.
 * Produces TokT / TokV / TokL plus an explicit indent stack (IndStk).
 *   N number   S string   F f-string   I identifier (name|case-sign)
 *   K keyword  O operator  W newline   > indent   < dedent   E eof
 */
const { E, S } = require('../dsl.js');
const L = require('./lib.js');

const KW = ' def return if elif else while for in break continue pass and or not is ' +
  'None True False import from class try except finally raise global nonlocal del ' +
  'assert lambda with yield as ';
const OPS2 = ' ** // == != <= >= += -= *= /= %= -> << >> ';

function tok(t, v) {
  return [S.ladd('TokT', E.str(t)), S.ladd('TokV', v), S.ladd('TokL', E.var('li'))];
}
const KWCHK = (nb) => E.contains(E.str(KW), E.join(E.str(' '), E.join(nb, E.str(' '))));

function body() {
  const le = () => E.var('le');
  const i = () => E.var('i');
  const ln = () => E.var('ln');
  const ch = (k) => E.letter(k, E.var('le'));

  // ---------------- one statement line ----------------
  const lineBody = [
    S.set('le', E.item('Code', E.var('li'))),
    S.set('ln', E.slen(E.var('le'))),
    S.set('i', E.num(1)),
    S.Until(E.or(E.gt(E.var('i'), E.var('ln')), E.not(E.eq(ch(E.var('i')), E.str(' ')))), [
      S.chg('i', E.num(1)),
    ]),
    S.set('ind', E.sub(E.var('i'), E.num(1))),
    S.set('sk', E.num(0)),
    S.If(E.or(E.gt(E.var('i'), E.var('ln')), E.eq(ch(E.var('i')), E.str('#'))), [S.set('sk', E.num(1))]),
    S.If(E.eq(E.var('sk'), E.num(0)), [
      // ---- indentation bookkeeping ----
      S.set('cur', E.item('IndStk', E.len('IndStk'))),
      S.If(E.gt(E.var('ind'), E.var('cur')), [
        S.If(E.ne(E.var('ind'), E.add(E.var('cur'), E.num(4))),
          [L.failAt(E.str('IndentationError: expected an indented block'), E.var('li'))]),
        S.ladd('IndStk', E.var('ind')),
        ...tok('>', E.str('')),
      ], [
        S.If(E.lt(E.var('ind'), E.var('cur')), [
          S.Until(E.or(E.le(E.item('IndStk', E.len('IndStk')), E.var('ind')), E.le(E.len('IndStk'), E.num(1))), [
            S.ldel('IndStk', E.len('IndStk')),
            ...tok('<', E.str('')),
          ]),
          S.If(E.ne(E.item('IndStk', E.len('IndStk')), E.var('ind')),
            [L.failAt(E.str('IndentationError: unindent does not match'), E.var('li'))]),
        ]),
      ]),
      // ---- tokenize the rest of the line ----
      S.Until(E.or(E.gt(E.var('i'), E.var('ln')), E.not(E.eq(E.var('err'), E.str('')))), [
        S.set('c0', ch(E.var('i'))),
        S.If(E.or(E.eq(E.var('c0'), E.str(' ')), E.eq(E.var('c0'), E.str('\t'))), [
          S.chg('i', E.num(1)),
        ], [
          S.If(E.eq(E.var('c0'), E.str('#')), [
            S.set('i', E.add(E.var('ln'), E.num(1))),
          ], [
            S.If(L.isAlpha(E.var('c0')), [identBlock()], [
              S.If(L.isDigit(E.var('c0')), [numberBlock()], [
                S.If(E.or(E.eq(E.var('c0'), E.str("'")), E.eq(E.var('c0'), E.str('"'))), [stringBlock()], [opBlock()]),
              ]),
            ]),
          ]),
        ]),
      ]),
      S.If(E.eq(E.var('err'), E.str('')), [...tok('W', E.str(''))]),
    ]),
  ];

  // ---------------- identifier ----------------
  function identBlock() {
    return [
      S.set('nb', E.str('')),
      S.set('sg', E.str('')),
      S.Until(E.or(E.gt(E.var('i'), E.var('ln')), E.not(L.isNameCh(ch(E.var('i'))))), [
        S.set('c0', ch(E.var('i'))),
        S.set('nb', E.join(E.var('nb'), E.var('c0'))),
        ...L.charCode(E.var('c0'), 'n0'),
        S.If(L.isUpperChar(E.var('n0')), [
          S.set('sg', E.join(E.var('sg'), E.str('1'))),
        ], [
          S.set('sg', E.join(E.var('sg'), E.str('0'))),
        ]),
        S.chg('i', E.num(1)),
      ]),
      S.If(E.and(
        E.or(E.eq(E.var('nb'), E.str('f')), E.eq(E.var('nb'), E.str('F'))),
        E.or(E.eq(ch(E.var('i')), E.str("'")), E.eq(ch(E.var('i')), E.str('"')))
      ), [
        ...stringBlock('F'),
      ], [
        S.If(E.and(KWCHK(E.var('nb')), E.not(E.contains(E.var('sg'), E.str('1')))), [
          ...tok('K', E.var('nb')),
        ], [
          ...tok('I', E.join(E.var('nb'), E.join(E.str('|'), E.var('sg')))),
        ]),
      ]),
    ];
  }

  // ---------------- number ----------------
  function numberBlock() {
    return [
      S.set('tx', E.str('')),
      S.set('brk', E.num(0)),
      S.set('dot', E.num(0)),
      S.Until(E.or(E.gt(E.var('i'), E.var('ln')), E.eq(E.var('brk'), E.num(1))), [
        S.set('c0', ch(E.var('i'))),
        S.If(L.isDigit(E.var('c0')), [
          S.set('tx', E.join(E.var('tx'), E.var('c0'))),
          S.chg('i', E.num(1)),
        ], [
          S.If(E.and(E.eq(E.var('c0'), E.str('.')), E.eq(E.var('dot'), E.num(0))), [
            S.set('dot', E.num(1)),
            S.set('tx', E.join(E.var('tx'), E.var('c0'))),
            S.chg('i', E.num(1)),
          ], [
            S.If(E.and(E.or(E.eq(E.var('c0'), E.str('e')), E.eq(E.var('c0'), E.str('E'))), E.gt(E.var('dot'), E.num(0))), [
              S.set('tx', E.join(E.var('tx'), E.str('e'))),
              S.chg('i', E.num(1)),
              S.set('c1', ch(E.var('i'))),
              S.If(E.or(E.eq(E.var('c1'), E.str('+')), E.eq(E.var('c1'), E.str('-'))), [
                S.set('tx', E.join(E.var('tx'), E.var('c1'))),
                S.chg('i', E.num(1)),
              ]),
              S.Until(E.or(E.gt(E.var('i'), E.var('ln')), E.not(L.isDigit(ch(E.var('i'))))), [
                S.set('tx', E.join(E.var('tx'), ch(E.var('i')))),
                S.chg('i', E.num(1)),
              ]),
            ], [
              S.set('brk', E.num(1)),
            ]),
          ]),
        ]),
      ]),
      ...tok('N', E.var('tx')),
    ];
  }

  // ---------------- string ----------------
  function stringBlock(kind) {
    const k = kind || 'S';
    return [
      S.set('q', ch(E.var('i'))),
      S.set('tx', E.str('')),
      S.chg('i', E.num(1)),
      S.set('brk', E.num(0)),
      S.Until(E.or(E.gt(E.var('i'), E.var('ln')), E.eq(E.var('brk'), E.num(1))), [
        S.set('c0', ch(E.var('i'))),
        S.If(E.eq(E.var('c0'), E.var('q')), [
          S.set('brk', E.num(1)),
        ], [
          S.If(E.eq(E.var('c0'), E.str('\\')), [
            S.chg('i', E.num(1)),
            S.set('c1', ch(E.var('i'))),
            S.If(E.eq(E.var('c1'), E.str('n')), [S.set('c1', E.str('\n'))]),
            S.If(E.eq(E.var('c1'), E.str('t')), [S.set('c1', E.str('\t'))]),
            S.If(E.eq(E.var('c1'), E.str('r')), [S.set('c1', E.str('\r'))]),
            S.set('tx', E.join(E.var('tx'), E.var('c1'))),
            S.chg('i', E.num(1)),
          ], [
            S.set('tx', E.join(E.var('tx'), E.var('c0'))),
            S.chg('i', E.num(1)),
          ]),
        ]),
      ]),
      S.chg('i', E.num(1)),
      ...tok(k, E.var('tx')),
    ];
  }

  // ---------------- operator ----------------
  function opBlock() {
    return [
      S.set('c0', ch(E.var('i'))),
      S.set('c1', ch(E.add(E.var('i'), E.num(1)))),
      S.set('tx', E.join(E.var('c0'), E.var('c1'))),
      S.If(E.contains(E.str(OPS2), E.join(E.str(' '), E.join(E.var('tx'), E.str(' ')))), [
        ...tok('O', E.var('tx')),
        S.chg('i', E.num(2)),
      ], [
        ...tok('O', E.var('c0')),
        S.chg('i', E.num(1)),
      ]),
    ];
  }

  return lineBody;
}

function build(em) {
  em.defineProc('Interpreter', 'lex_all', [], () => [
    S.ldelall('TokT'), S.ldelall('TokV'), S.ldelall('TokL'), S.ldelall('IndStk'),
    S.ladd('IndStk', E.num(0)),
    S.set('li', E.num(1)),
    S.Repeat(E.len('Code'), [
      S.If(E.eq(E.var('err'), E.str('')), body()),
      S.chg('li', E.num(1)),
    ]),
    S.If(E.eq(E.var('err'), E.str('')), [
      S.Until(E.le(E.len('IndStk'), E.num(1)), [
        S.ldel('IndStk', E.len('IndStk')),
        ...tok('<', E.str('')),
      ]),
      ...tok('E', E.str('')),
    ]),
  ], true);
}

module.exports = { build, KW, OPS2 };

'use strict';
/**
 * v5 kernel assembly.  Every procedure is a LEAF (never calls another custom
 * block); only the RUN / flag hats glue procedures together.
 */
const { E, S } = require('../dsl.js');
const L = require('./lib.js');
const lex = require('./lex.js');

// ---- Interpreter-private storage (all kernel state lives in lists) ----
const LISTS = [
  // code image
  'Iop', 'Ia', 'Ib', 'Iline', 'Kval',
  // runtime stacks
  'Stk', 'FrKind', 'FrRet', 'FrEnv', 'FrBase', 'FrTop',
  // binding chains / maps
  'BindName', 'BindVal', 'BindNext', 'MapHead', 'MapParent', 'MapKind',
  // symbol tables
  'FnKind', 'FnName', 'FnArity', 'FnParam', 'FnBody', 'FnEnv', 'FnFlags',
  'ClName', 'ClBase', 'ClMap', 'InClass', 'InMap',
  // heap
  'LStart', 'LCount', 'LCap', 'LArr',
  // lexer / parser / compiler working space
  'TokT', 'TokV', 'TokL', 'IndStk',
  'NdK', 'NdA', 'NdS', 'NdN', 'NdC',
  'PatchSite', 'PatchSlot',
];
// scratch registers (leaf procedures may use these as locals)
const VARS = [
  'pc', 'sp', 'frTop', 'tk', 'ip', 'err', 'hTop', 'bTop',
  'li', 'le', 'ln', 'i', 'j', 'c0', 'c1', 'nb', 'sg', 'tx', 'brk', 'dot', 'q',
  'ind', 'cur', 'sk', 'n0', 'n1', 'n2', 'ti', 'c9', 'n9',
  'tmp', 'tmp2', 't0', 't1', 't2', 't3', 't4', 't5',
  'a0', 'a1', 'a2', 'a3', 'b0', 'b1', 'b2', 'b3',
];

function build(em, project) {
  for (const n of VARS) em.addVar('Interpreter', n, 0);
  for (const n of LISTS) em.addList('Interpreter', n, []);

  // ---------------- procedures ----------------
  em.defineProc('Interpreter', 'reset_vm', [], () => [
    S.set('pc', E.num(0)), S.set('sp', E.num(0)), S.set('frTop', E.num(0)), S.set('tk', E.num(0)),
    S.set('ip', E.num(0)), S.set('err', E.str('')), S.set('hTop', E.num(0)), S.set('bTop', E.num(0)),
    ...LISTS.map((n) => S.ldelall(n)),
  ], true);

  em.defineProc('Interpreter', 'print_line', ['msg'], () => printLine(em), true);

  em.defineProc('Interpreter', 'dump_tok', [], () => [
    S.set('i', E.num(1)),
    S.Repeat(E.len('TokT'), [
      ...L.outLine(E.join(E.item('TokT', E.var('i')), E.join(E.str(' '),
        E.join(E.item('TokV', E.var('i')), E.join(E.str(' @'), E.item('TokL', E.var('i'))))))),
      S.chg('i', E.num(1)),
    ]),
  ], true);

  lex.build(em);

  // ---------------- hats ----------------
  em.hat('Interpreter', 'event_whenflagclicked', {}, [
    S.raw('looks_hide', [], {}),
    S.Call('reset_vm', []),
  ]);

  em.hat('Interpreter', 'event_whenbroadcastreceived', { BROADCAST_OPTION: 'HALT' }, [
    S.raw('control_stop', [], { STOP_OPTION: 'other scripts in sprite' }),
    S.set('running', E.num(0)),
    S.set('busy', E.num(0)),
    S.set('dirty', E.num(1)),
  ]);

  em.hat('Interpreter', 'event_whenbroadcastreceived', { BROADCAST_OPTION: 'RUN' }, [
    S.set('error', E.str('')),
    S.set('status', E.str('Running')),
    S.set('steps', E.num(0)),
    S.set('pc', E.num(0)),
    S.ldelall('Output'), S.ldelall('Names'), S.ldelall('Values'), S.ldelall('Types'),
    S.set('outpage', E.num(1)),
    S.set('varpage', E.num(1)),
    S.Call('reset_vm', []),
    S.Call('lex_all', []),
    S.If(E.eq(E.var('err'), E.str('')), [
      S.If(E.eq(E.item('Code', E.num(1)), E.str('#!dump')), [
        S.Call('dump_tok', []),
      ], [
        S.Call('print_line', [E.join(E.str('v5 lex ok, tokens='), E.len('TokT'))]),
      ]),
    ], [
      S.Call('print_line', [E.join(E.str('Error: '), E.var('err'))]),
      S.set('error', E.var('err')),
      S.set('status', E.str('Error / see console')),
    ]),
    S.set('running', E.num(0)),
    S.set('busy', E.num(0)),
    S.set('dirty', E.num(1)),
  ]);
}

function printLine(em) {
  const msg = em.arg('msg');
  return [
    S.set('tmp', E.str('')),
    S.set('ti', E.num(1)),
    S.Repeat(E.slen(msg), [
      S.set('tmp', E.join(E.var('tmp'), E.letter(E.var('ti'), msg))),
      S.If(E.eq(E.slen(E.var('tmp')), E.num(30)), [
        S.ladd('Output', E.var('tmp')),
        S.set('tmp', E.str('')),
      ]),
      S.chg('ti', E.num(1)),
    ]),
    S.If(E.or(E.not(E.eq(E.var('tmp'), E.str(''))), E.eq(E.slen(msg), E.num(0))), [
      S.ladd('Output', E.var('tmp')),
    ]),
    S.While(E.gt(E.len('Output'), E.num(300)), [S.ldel('Output', E.num(1))]),
    S.set('outpage', E.num(1)),
    S.set('dirty', E.num(1)),
  ];
}

module.exports = { build, LISTS, VARS, printLine };

