'use strict';
/**
 * v5 Compiler - explicit work stack, post-order emission, jump backpatching.
 */
const { E, S } = require('../dsl.js');
const A = require('./ast.js');
const L = require('./lib.js');
const U = require('./astutil.js');

const NdK = (nd) => E.item('NdK', nd);
const NdA = (nd) => E.item('NdA', nd);
const NdN = (nd) => E.item('NdN', nd);
const Ch = (nd, k) => E.item('NdC', E.add(E.item('NdS', nd), E.num(k)));
const heapGet = U.heapGet;

function build() {
  // ---- task stack: kind 'n' visit node / 'e' emit ----
  const pushT = (k, a, b) => L.pushRow('csSp', [['CtK', E.str(k)], ['CtA', a], ['CtB', b === undefined ? E.str('') : b]]);
  const emit = (op, a, b) => [
    S.ladd('Iop', E.str(op)),
    S.ladd('Ia', a === undefined ? E.str('') : a),
    S.ladd('Ib', b === undefined ? E.str('') : b),
    S.ladd('Iline', E.num(0)),
  ];
  const here = () => E.add(E.len('Iop'), E.num(1));
  const patchA = (site) => [S.setAt2 ? null : S.lset('Ia', site, here())];
  const patchB = (site) => [S.lset('Ib', site, here())];
  const addK = (v) => [S.ladd('Kval', v), S.set('kci', E.len('Kval'))];

  // push statements of a suite in reverse so they pop in order
  function pushSuiteReverse(suiteNd) {
    return [
      S.set('j', E.item('LCount', NdA(suiteNd))),
      S.Until(E.le(E.var('j'), E.num(0)), [
        ...pushT('n', heapGet(NdA(suiteNd), E.var('j'))),
        S.chg('j', E.num(-1)),
      ]),
    ];
  }

  /** compile one assignment to a target already holding nothing on the stack */
  function storeTo(tgt) {
    return [
      S.If(E.eq(NdK(tgt), E.str('name')), [
        S.set('t7', NdA(tgt)),
        ...emit('STOREV', E.var('t7')),
      ], [
        S.If(E.eq(NdK(tgt), E.str('sub')), [
          ...pushT('n', Ch(tgt, E.num(0))),
          ...pushT('e', E.str('SUBSSET'), NdA(tgt)),
        ], [
          S.If(E.eq(NdK(tgt), E.str('attr')), [
            S.set('t7', NdA(tgt)),
            ...pushT('n', Ch(tgt, E.num(0))),
            ...pushT('e', E.str('SETATTR'), E.var('t7')),
          ], [
            L.failAt(E.str('SyntaxError: bad assignment target'), E.num(0)),
          ]),
        ]),
      ]),
    ];
  }

  // ------------------------------------------------ node visitor
  function visit() {
    const nd = () => E.var('cnd');
    return [
      S.set('cnd', E.item('CtA', E.var('csSp'))),
      S.chg('csSp', E.num(-1)),
      S.set('ck', NdK(E.var('cnd'))),
      // ---------- expressions ----------
      S.If(E.eq(E.var('ck'), E.str('lit')), [...addK(NdA(E.var('cnd'))), ...emit('PUSHK', E.var('kci'))]),

      S.If(E.eq(E.var('ck'), E.str('name')), [...emit('PUSHV', NdA(E.var('cnd')))]),

      S.If(E.eq(E.var('ck'), E.str('bin')), [
        ...pushT('e', E.str('BIN'), NdA(E.var('cnd'))),
        ...pushT('n', Ch(E.var('cnd'), E.num(1))),
        ...pushT('n', Ch(E.var('cnd'), E.num(0))),
      ]),

      S.If(E.eq(E.var('ck'), E.str('un')), [
        ...pushT('e', E.str('UN'), NdA(E.var('cnd'))),
        ...pushT('n', Ch(E.var('cnd'), E.num(0))),
      ]),

      S.If(E.eq(E.var('ck'), E.str('cmp')), [
        ...pushT('e', E.str('CMP'), E.join(NdA(E.var('cnd')), E.join(E.str('|'), NdN(E.var('cnd'))))),
        S.set('k', NdN(E.var('cnd'))),
        S.Until(E.le(E.var('k'), E.num(0)), [
          ...pushT('n', Ch(E.var('cnd'), E.var('k'))),
          S.chg('k', E.num(-1)),
        ]),
      ]),

      S.If(E.eq(E.var('ck'), E.str('call')), [
        ...pushT('e', E.str('CALL'), E.join(E.join(NdA(E.var('cnd')), E.str('|')), NdN(E.var('cnd')))),
        S.set('k', NdN(E.var('cnd'))),
        S.Until(E.le(E.var('k'), E.num(0)), [
          ...pushT('n', Ch(E.var('cnd'), E.var('k'))),
          S.chg('k', E.num(-1)),
        ]),
      ]),

      S.If(E.eq(E.var('ck'), E.str('attr')), [
        ...pushT('e', E.str('GETATTR'), NdA(E.var('cnd'))),
        ...pushT('n', Ch(E.var('cnd'), E.num(0))),
      ]),

      S.If(E.eq(E.var('ck'), E.str('sub')), [
        ...pushT('e', E.str('SUBS'), NdA(E.var('cnd'))),
        S.set('k', NdN(E.var('cnd'))),
        S.Until(E.le(E.var('k'), E.num(0)), [
          ...pushT('n', Ch(E.var('cnd'), E.var('k'))),
          S.chg('k', E.num(-1)),
        ]),
      ]),

      S.If(E.eq(E.var('ck'), E.str('list')), [
        ...pushT('e', E.str('BUILD'), E.str('L')),
        S.set('k', NdN(E.var('cnd'))),
        S.Until(E.le(E.var('k'), E.num(0)), [
          ...pushT('n', Ch(E.var('cnd'), E.var('k'))),
          S.chg('k', E.num(-1)),
        ]),
      ]),

      S.If(E.eq(E.var('ck'), E.str('tuple')), [
        ...pushT('e', E.str('BUILD'), E.str('T')),
        S.set('k', NdN(E.var('cnd'))),
        S.Until(E.le(E.var('k'), E.num(0)), [
          ...pushT('n', Ch(E.var('cnd'), E.var('k'))),
          S.chg('k', E.num(-1)),
        ]),
      ]),

      S.If(E.eq(E.var('ck'), E.str('dict')), [
        ...pushT('e', E.str('BUILD'), E.str('D')),
        S.set('k', NdN(E.var('cnd'))),
        S.Until(E.le(E.var('k'), E.num(0)), [
          ...pushT('n', Ch(E.var('cnd'), E.var('k'))),
          S.chg(E.var('k'), E.num(-1)),
        ]),
      ]),

      // ---------- statements ----------
      S.If(E.eq(E.var('ck'), E.str('suite')), [...pushSuiteReverse(E.var('cnd'))]),

      S.If(E.eq(E.var('ck'), E.str('expr')), [
        ...pushT('e', E.str('POP')),
        ...pushT('n', Ch(E.var('cnd'), E.num(0))),
      ]),

      S.If(E.eq(E.var('ck'), E.str('assign')), [assignStmt()]),
      S.If(E.eq(E.var('ck'), E.str('ret')), [
        ...pushT('e', E.str('RET')),
        S.If(E.ge(NdN(E.var('cnd')), E.num(1)), [...pushT('n', Ch(E.var('cnd'), E.num(0)))],
          [...addK(E.str('Z')), ...pushT('e', E.str('PUSHK'), E.var('kci'))]),
      ]),
      S.If(E.eq(E.var('ck'), E.str('pass')), [...emit('NOP')]),
      S.If(E.eq(E.var('ck'), E.str('break')), [...emit('JMP', E.num(0)), ...recordBreak()]),
      S.If(E.eq(E.var('ck'), E.str('cont')), [
        S.If(E.le(E.var('lpSp'), E.num(0)), [...L.failAt(E.str('SyntaxError: continue outside loop'), E.num(0))],
          [...emit('JMP', E.item('LpCon', E.var('lpSp')))]),
      ]),
      S.If(E.eq(E.var('ck'), E.str('if')), [ifStmt(0)]),
      S.If(E.eq(E.var('ck'), E.str('while')), [whileStmt()]),
      S.If(E.eq(E.var('ck'), E.str('for')), [forStmt()]),
      S.If(E.eq(E.var('ck'), E.str('def')), [defStmt('DEF')]),
      S.If(E.eq(E.var('ck'), E.str('lam')), [defStmt('LAMBDA')]),
      S.If(E.eq(E.var('ck'), E.str('class')), [classStmt()]),
      S.If(E.eq(E.var('ck'), E.str('global')), [...emit('GLOBAL', ...constOf(NdA(E.var('cnd'))))]),
      S.If(E.eq(E.var('ck'), E.str('nonloc')), [...emit('NONLOCAL', ...constOf(NdA(E.var('cnd'))))]),
      S.If(E.eq(E.var('ck'), E.str('del')), [
        S.If(E.eq(NdK(Ch(E.var('cnd'), E.num(0))), E.str('name')), [
          ...emit('DELV', NdA(Ch(E.var('cnd'), E.num(0)))),
        ], [L.failAt(E.str('SyntaxError: del needs a name'), E.num(0))]),
      ]),
      S.If(E.eq(E.var('ck'), E.str('asrt')), [
        ...pushT('e', E.str('ASRT2')),
        ...pushT('e', E.str('ASRT')),
        S.If(E.ge(NdN(E.var('cnd')), E.num(2)), [...pushT('n', Ch(E.var('cnd'), E.num(1)))],
          [...addK(E.str('Z')), ...pushT('e', E.str('PUSHK'), E.var('kci'))]),
        ...pushT('n', Ch(E.var('cnd'), E.num(0))),
      ]),
      S.If(E.eq(E.var('ck'), E.str('raise')), [
        ...pushT('e', E.str('RAISE')),
        S.If(E.ge(NdN(E.var('cnd')), E.num(1)), [...pushT('n', Ch(E.var('cnd'), E.num(0)))],
          [...addK(E.str('Z')), ...pushT('e', E.str('PUSHK'), E.var('kci'))]),
      ]),
      S.If(E.eq(E.var('ck'), E.str('import')), [
        ...pushT('e', E.str('IMPORT'), NdA(E.var('cnd'))),
      ]),
      S.If(E.eq(E.var('ck'), E.str('from')), [
        ...pushT('e', E.str('IMPORTFROM'), NdA(E.var('cnd'))),
      ]),
      S.If(E.eq(E.var('ck'), E.str('try')), [tryStmt()]),
      S.If(E.eq(E.var('ck'), E.str('excas')), [
        // except Type as name -> handled inline by tryStmt; keep as a marker node
        ...pushT('n', Ch(E.var('cnd'), E.num(0))),
      ]),
      S.If(E.eq(E.var('ck'), E.str('asname')), [...addK(NdA(E.var('cnd'))), ...emit('PUSHK', E.var('kci'))]),
    ];
  }

  function constOf(vExpr) {
    return [S.ladd('Kval', vExpr), S.set('kci', E.len('Kval'))].concat([]);
  }

  function assignStmt() {
    const nd = () => E.var('cnd');
    return [
      S.set('cn2', NdN(nd())),
      S.set('cop', E.item('NdA', nd())),
      // value is the last child
      S.If(E.contains(E.var('cop'), E.str('|')), [
        S.set('cn2', E.num(0)),
        S.set('k', E.num(1)),
        S.Until(E.gt(E.var('k'), E.slen(E.var('cop'))), [
          S.If(E.eq(E.letter(E.var('k'), E.var('cop')), E.str('|')), [S.set('cn2', E.num(1))], []),
          S.chg('k', E.num(1)),
        ]),
        S.set('cn2', E.sub(NdN(nd()), E.num(1))),
        S.set('cop', E.item('NdA', nd())),
        S.set('cop', E.sub(E.var('cop'), E.num(0))),
      ]),
      // targets = cn2, value = child cn2
      S.If(E.eq(E.var('cop'), E.str('=')), [
        ...pushT('n', Ch(nd(), NdN(nd()))),
        S.set('k', E.num(1)),
        S.Until(E.gt(E.var('k'), NdN(nd())), [
          // keep one copy for each remaining target
          S.If(E.lt(E.var('k'), NdN(nd())), [...pushT('e', E.str('DUP'))]),
          ...pushT('e', E.str('STORE'), E.num(-1)),
          ...pushT('n', E.str(-1)),
          S.chg(E.var('k'), E.num(1)),
        ]),
      ], [
        L.failAt(E.str('SyntaxError: unsupported assignment'), E.num(0)),
      ]),
    ];
  }

  function recordBreak() {
    return [
      S.If(E.le(E.var('lpSp'), E.num(0)), [...L.failAt(E.str('SyntaxError: break outside loop'), E.num(0))],
        [...L.heapAdd(E.item('LpBrk', E.var('lpSp')), E.sub(E.len('Iop'), E.num(0)))]),
    ];
  }

  function ifStmt(depth) { return [ ...emit('NOP') ]; }
  function whileStmt() { return [ ...emit('NOP') ]; }
  function forStmt() { return [ ...emit('NOP') ]; }
  function defStmt(op) { return [ ...emit('NOP') ]; }
  function classStmt() { return [ ...emit('NOP') ]; }
  function tryStmt() { return [ ...emit('NOP') ]; }

  return [
    S.ldelall('Iop'), S.ldelall('Ia'), S.ldelall('Ib'), S.ldelall('Iline'), S.ldelall('Kval'),
    S.set('csSp', E.num(0)), S.set('lpSp', E.num(0)),
    ...pushT('n', E.var('rootNd')),
    S.Until(E.or(E.le(E.var('csSp'), E.num(0)), E.not(E.eq(E.var('err'), E.str('')))), [
      S.If(E.eq(E.item('CtK', E.var('csSp')), E.str('e')), [
        S.set('cop0', E.item('CtA', E.var('csSp'))),
        S.set('ca0', E.item('CtB', E.var('csSp'))),
        S.chg('csSp', E.num(-1)),
