        S.If(E.eq(E.var('t6'), E.num(0)), [
          S.If(E.and(E.eq(T(), E.str('O')), E.eq(v(), E.str('='))), [
            ...heapAdd(E.var('stL'), E.item('Pv', E.var('pvSp'))),
