        S.chg('pvSp', E.num(-1)), S.chg('pkSp', E.num(-1)),
        S.lset('BlS', E.var('blSp'), E.num(2)),
        tp1(), S.set('stK', E.str('')), S.set('ps', E.num(0)), S.set('t6', E.num(1)),
      ]),
      // return value
      S.If(E.and(E.eq(E.var('t6'), E.num(0)), E.eq(k(), E.str('hret'))), [
