  function classBlock() {
    const ia = () => E.item('Ia', E.var('pc'));
    const ib = () => E.item('Ib', E.var('pc'));
    return [
      S.set('spec', E.item('Kval', ia())),
      S.set('split', E.num(0)), S.set('j', E.num(1)),
      S.Until(E.gt(E.var('j'), E.slen(E.var('spec'))), [
