  }

  function reraiseBlock() {
    return [
      S.set('exv', E.var('curEx')), S.set('handled', E.num(0)),
      S.Until(E.or(E.le(E.var('hdTop'), E.num(0)), E.eq(E.var('handled'), E.num(1))), [
        S.set('hpc', E.item('HdPc', E.var('hdTop'))),
