  // ================= CALL =================
  function callBlock() {
    const ia = () => E.item('Ia', E.var('pc'));
    return [
      S.set('nspec', E.num(0)), S.set('nargs', E.num(2)),
      S.set('j', E.num(1)),
      S.Until(E.gt(E.var('j'), E.slen(ia())), [
        S.If(E.eq(E.letter(E.var('j'), ia()), E.str('|')), [
