  function instantiate() {
    return [
      ...L.payInto(E.var('fval'), 'clo'),
      S.chg('iTop', E.num(1)), S.set('ino', E.var('iTop')),
      ...L.setAt('InClass', E.var('ino'), E.var('clo')),
      ...mapNew('imap', E.item('ClMap', E.var('clo')), E.str('I')),
      ...L.setAt('InMap', E.var('ino'), E.var('imap')),
