  }

  function callBuiltin(nameExpr) { return [ S.set('bname', nameExpr), builtinBody() ]; }

  function builtinBody() {
    const bn = () => E.var('bname');
    return [
      S.If(E.eq(bn(), E.str('print|00000')), [printBuiltin()]),
      S.If(E.eq(bn(), E.str('len|000')), [
        ...vpop('xv'),
        S.set('res2', E.num(0)),
        S.If(E.eq(E.letter(E.num(1), E.var('xv')), E.str('S')), [S.set('res2', E.sub(E.slen(E.var('xv')), E.num(1)))]),
        S.If(E.or(E.eq(E.letter(E.num(1), E.var('xv')), E.str('L')), E.eq(E.letter(E.num(1), E.var('xv')), E.str('T'))), [
          ...L.payInto(E.var('xv'), 'lso'), S.set('res2', E.item('LCount', E.var('lso'))),
        ]),
        S.chg('sp', E.mul(E.num(-1), E.var('nargs'))),
        ...vpush(E.join(E.str(''), E.var('res2'))),
      ]),
      S.If(E.eq(bn(), E.str('range|00000')), [rangeBuiltin()]),
      S.If(E.eq(bn(), E.str('int|000')), [
        ...vpop('xv'), ...L.payInto(E.var('xv'), 'na'), S.set('res2', E.rnd(E.var('na'))),
        S.chg('sp', E.mul(E.num(-1), E.var('nargs'))),
        ...vpush(E.join(E.str(''), E.var('res2'))),
      ]),
      S.If(E.eq(bn(), E.str('str|000')), [
        ...vpop('xv'), ...tostr(E.var('xv'), 'res2'),
        S.chg('sp', E.mul(E.num(-1), E.var('nargs'))),
        ...vpush(E.join(E.str('S'), E.var('res2'))),
      ]),
      S.If(E.eq(bn(), E.str('abs|000')), [
        ...vpop('xv'), ...L.payInto(E.var('xv'), 'na'), S.set('res2', E.math('abs', E.var('na'))),
        S.chg('sp', E.mul(E.num(-1), E.var('nargs'))),
        ...vpush(E.join(E.str(''), E.var('res2'))),
      ]),
      S.If(E.eq(bn(), E.str('ord|000')), [
        ...vpop('xv'), ...L.payInto(E.var('xv'), 'na'),
        ...L.charCode(E.letter(E.num(1), E.var('na')), 'ca'),
        S.set('res2', E.add(E.var('ca'), E.num(31))),
        S.chg('sp', E.mul(E.num(-1), E.var('nargs'))),
        ...vpush(E.join(E.str(''), E.var('res2'))),
      ]),
      S.If(E.eq(bn(), E.str('chr|000')), [
        ...vpop('xv'), ...L.payInto(E.var('xv'), 'na'),
        S.set('res2', E.letter(E.sub(E.var('na'), E.num(31)), E.str(L.NUMSTART.replace('-.', '')))),
