      S.If(E.eq(bn(), E.str('float|00000')), [
        ...vpop('xv'), ...L.payInto(E.var('xv'), 'na'), S.set('res2', E.add(E.var('na'), E.num(0))),
        S.chg('sp', E.mul(E.num(-1), E.var('nargs'))),
        ...vpush(E.join(E.str(''), E.var('res2'))),
      ]),
      S.If(E.eq(bn(), E.str('bool|0000')), [
        ...vpop('xv'), ...truthOf(E.var('xv'), 'tb'), S.set('res2', E.str('B0')),
        S.If(E.eq(E.var('tb'), E.num(1)), [S.set('res2', E.str('B1'))]),
        S.chg('sp', E.mul(E.num(-1), E.var('nargs'))),
        ...vpush(E.var('res2')),
      ]),
      S.If(E.eq(bn(), E.str('type|0000')), [
        ...vpop('xv'),
        S.set('res2', E.str("<class 'int'>")),
        S.If(E.eq(E.letter(E.num(1), E.var('xv')), E.str('S')), [S.set('res2', E.str("<class 'str'>"))]),
        S.If(E.eq(E.letter(E.num(1), E.var('xv')), E.str('B')), [S.set('res2', E.str("<class 'bool'>"))]),
        S.If(E.eq(E.letter(E.num(1), E.var('xv')), E.str('Z')), [S.set('res2', E.str("<class 'NoneType'>"))]),
        S.If(E.eq(E.letter(E.num(1), E.var('xv')), E.str('L')), [S.set('res2', E.str("<class 'list'>"))]),
        S.If(E.eq(E.letter(E.num(1), E.var('xv')), E.str('T')), [S.set('res2', E.str("<class 'tuple'>"))]),
        S.If(E.eq(E.letter(E.num(1), E.var('xv')), E.str('D')), [S.set('res2', E.str("<class 'dict'>"))]),
        S.If(E.not(E.contains(E.str('-.0123456789'), E.letter(E.num(1), E.var('xv')))), [
          S.If(E.not(E.eq(E.letter(E.num(1), E.var('xv')), E.str('S'))), [
            S.If(E.not(E.eq(E.letter(E.num(1), E.var('xv')), E.str('B'))), [
              S.If(E.not(E.eq(E.letter(E.num(1), E.var('xv')), E.str('Z'))), [
                S.If(E.not(E.eq(E.letter(E.num(1), E.var('xv')), E.str('L'))), [
                  S.If(E.not(E.eq(E.letter(E.num(1), E.var('xv')), E.str('T'))), [
