        S.set('out', E.join(E.var('out'), E.var('argt'))),
        S.set('first', E.num(0)),
        S.chg('i', E.num(1)),
      ]),
      S.chg('sp', E.mul(E.num(-1), E.var('nargs'))),
      ...vmPrint(E.var('out')),
      ...vpush(E.str('Z')),
    ];
  }

  function vmPrint(msgExpr) {
    return [
      S.set('pl', E.str('')), S.set('pi2', E.num(1)),
      S.Repeat(E.slen(msgExpr), [
        S.set('pl', E.join(E.var('pl'), E.letter(E.var('pi2'), msgExpr))),
        S.If(E.eq(E.slen(E.var('pl')), E.num(30)), [
          S.ladd('Output', E.var('pl')), S.set('pl', E.str('')),
        ]),
        S.chg('pi2', E.num(1)),
      ]),
      S.If(E.or(E.not(E.eq(E.var('pl'), E.str(''))), E.eq(E.slen(msgExpr), E.num(0))), [
        S.ladd('Output', E.var('pl')),
