        ...L.payInto(E.item('Stk', E.add(E.var('ubase'), E.num(2))), 'r0'),
        ...L.payInto(E.item('Stk', E.add(E.var('ubase'), E.num(3))), 'r1'),
      ]),
      S.If(E.eq(E.var('nargs'), E.num(4)), [
        ...L.payInto(E.item('Stk', E.add(E.var('ubase'), E.num(2))), 'r0'),
        ...L.payInto(E.item('Stk', E.add(E.var('ubase'), E.num(3))), 'r1'),
        ...L.payInto(E.item('Stk', E.add(E.var('ubase'), E.num(4))), 'r2'),
      ]),
      ...heapNew('tobj'),
      S.set('rv', E.var('r0')),
      S.Until(E.or(E.ge(E.var('rv'), E.var('r1')), E.le(E.var('r2'), E.num(0))), [
        S.If(E.lt(E.var('rv'), E.var('r1')), [...heapPush(E.var('tobj'), E.join(E.str(''), E.var('rv')))]),
        S.set('rv', E.add(E.var('rv'), E.var('r2'))),
      ]),
      S.chg('sp', E.mul(E.num(-1), E.var('nargs'))),
      ...vpush(E.join(E.str('L'), E.var('tobj'))),
    ];
  }

  function methBlock() { return [ ...L.failAt(E.str('NotImplementedError: method call'), E.var('pc')) ]; }

  return [
    S.set('pc', E.num(1)), S.set('halted', E.num(0)), S.set('ticks', E.num(0)),
    S.Until(E.or(E.eq(E.var('halted'), E.num(1)), E.not(E.eq(E.var('err'), E.str('')))), [
      S.set('op', E.item('Iop', E.var('pc'))),
      ...dispatch(),
      S.If(E.eq(E.var('halted'), E.num(0)), [S.chg('pc', E.num(1))]),
      S.chg('ticks', E.num(1)),
      S.If(E.or(E.eq(E.var('speed'), E.num(0)), E.eq(E.mod(E.var('ticks'), E.num(2000)), E.num(0))), [
        S.set('steps', E.var('ticks')),
        S.set('dirty', E.num(1)),
        S.Wait(E.num(0)),
      ]),
    ]),
    S.set('steps', E.var('ticks')),
  ];
}

function setup(em) { em.defineProc('Interpreter', 'vm_run', [], () => build(), false); }
module.exports = { build: build, setup: setup, key: key, BUILTINS: BUILTINS };

