  if (!tgt) return { skipped: true };
  const blocks = tgt.blocks;
  const varsDict = tgt.variables || {};
  const NEWLINE = String.fromCharCode(10);

  // ---------- 1. script + region of every block (iterative: chains get long) ----------
  const scriptOf = Object.create(null);
  const regionOf = Object.create(null);
  function up(id, memo, key) {
    const path = [];
    let c = id;
    while (c !== undefined && c !== null && memo[c] === undefined) {
      const b = blocks[c];
      if (!b) { memo[c] = c; break; }
      if (b.topLevel) { memo[c] = c; break; }
      if (key === 'region' && (b.parent_input === 'SUBSTACK' || b.parent_input === 'SUBSTACK2')) {
        memo[c] = c; break;
      }
      path.push(c);
      c = b.parent;
    }
    const v = c === undefined || c === null ? id : memo[c];
    for (let i = path.length - 1; i >= 0; i--) memo[path[i]] = v;
    return memo[id] === undefined ? id : memo[id];
  }
  for (const id in blocks) { up(id, scriptOf, 'script'); up(id, regionOf, 'region'); }

  // ---------- 2. definite assignment: flag variables read before any write ----------
  const rwFlag = Object.create(null);
