'use strict';
const fs = require('fs');
const realLog = console.log.bind(console);
for (const k of ['log','warn','error','info','debug','trace']) console[k] = () => {};
const VM = require('D:/users/OneDrive/Desktop/scratch-vm-test/node_modules/scratch-vm');
const projectPath = process.argv[2];
const codePath = process.argv[3];
(async () => {
  const vm = new VM();
  await vm.loadProject(fs.readFileSync(projectPath));
  const runtime = vm.runtime;
  const stage = runtime.getTargetForStage();
  const interp = runtime.targets.find(t => t.sprite && t.sprite.name === 'Interpreter');
  const vals = (m) => (m && typeof m.values === 'function') ? [...m.values()] : Object.values(m || {});
  const sv = (t, n) => vals(t.variables).find((v) => v.name === n && v.type !== 'list');
  const sl = (t, n) => vals(t.variables).find((v) => v.name === n && v.type === 'list');
  const setList = (t, n, arr) => { const l = sl(t, n); l.value.length = 0; for (const x of arr) l.value.push(x); };
  vm.start(); vm.greenFlag();
  for (let i = 0; i < 10; i++) runtime._step();
  const lines = fs.readFileSync(codePath, 'utf8').replace(/\r/g, '').split('\n');
  setList(stage, 'Code', lines);
  setList(stage, 'Output', []);
  for (const n of ['mode','ticket','stopreq','running']) { const v = sv(stage, n); if (v) v.value = 0; }
  sv(stage, 'ticket').value = 1;
  const spd = sv(stage, 'speed'); if (spd) spd.value = Number(process.env.PERF_SPEED || 1);
  const t0 = Date.now();
  runtime.startHats('event_whenbroadcastreceived', { BROADCAST_OPTION: 'RUN' });
  let frames = 0, lastLen = -1, stable = 0;
  for (; frames < 400000; frames++) {
    runtime._step();
    const L = (sl(stage, 'Output') || { value: [] }).value.length;
    if (frames > 2 && String(sv(stage, 'running').value) === '0') break;
    if (L === lastLen) { stable++; if (stable > 3000) break; } else { stable = 0; lastLen = L; }
  }
  const ms = Date.now() - t0;
  const instr = Number(sv(interp, 'steps') ? sv(interp, 'steps').value : 0);
  const out = (sl(stage, 'Output') || { value: [] }).value.slice(-2);
  realLog('frames=' + frames + ' vmInstructions=' + instr + ' instr/frame=' + (frames ? (instr / frames).toFixed(0) : 'n/a') + ' wall=' + ms + 'ms' + ' ips=' + (ms ? Math.round(instr / ms * 1000) : 0));
  realLog('tail output: ' + JSON.stringify(out));
  realLog('status=' + sv(interp, 'status').value + ' error=' + sv(interp, 'error').value);
})();

